-- rowfence 0.1.0-dev: canonical_share_ids. Generated by rowfence migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowfence makes of it changed

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute
             WHERE attrelid = to_regclass('authz.policy_versions') AND attname = 'lock' AND NOT attisdropped) THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock IS DISTINCT FROM 'dda6e9fd4e983a53' THEN
    RAISE EXCEPTION 'rowfence: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'dda6e9fd4e983a53', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowfence push or apply since needs the '
                   'migrations from the start (or rowfence apply of the policy the previous migration left)';
  END IF;
END $authz_guard$;

-- Functions below resolve names with the search_path in effect now, temporary schema last
DO $sp$ BEGIN PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ',
  nullif(pg_catalog.current_setting('search_path'), ''), 'pg_temp'), true); END $sp$;

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', 'applying the policy: the row was deleted', true); END $r$;

-- Shares stored with ids that aren't canonical ('007', an uppercase uuid: written directly before every
-- write went through authz_int.canon) are made canonical, since the sweep below and the triggers compare
-- text; one that then repeats a share already stored goes, the first made staying
CREATE TEMP TABLE authz_uncanonical ON COMMIT DROP AS
  SELECT g.ctid AS row, authz_int.canon(g.object_type, g.object_id) AS object_id,
         authz_int.canon(g.subject_type, g.subject_id) AS subject_id
  FROM authz.shares g
  WHERE g.object_id IS DISTINCT FROM authz_int.canon(g.object_type, g.object_id)
     OR g.subject_id IS DISTINCT FROM authz_int.canon(g.subject_type, g.subject_id);
DELETE FROM authz.shares g USING authz_uncanonical u
WHERE g.ctid = u.row AND EXISTS (
  SELECT 1 FROM authz.shares c WHERE c.object_type = g.object_type AND c.object_id = u.object_id AND c.relation = g.relation
    AND c.subject_type = g.subject_type AND c.subject_id = u.subject_id AND c.subject_relation = g.subject_relation);
DELETE FROM authz.shares g USING (
  SELECT u.row, row_number() OVER (PARTITION BY s.object_type, u.object_id, s.relation, s.subject_type, u.subject_id,
                                   s.subject_relation ORDER BY s.created_at, u.row) AS n
  FROM authz_uncanonical u JOIN authz.shares s ON s.ctid = u.row) d
WHERE g.ctid = d.row AND d.n > 1;
UPDATE authz.shares g SET object_id = u.object_id, subject_id = u.subject_id FROM authz_uncanonical u WHERE g.ctid = u.row;
DROP TABLE authz_uncanonical;

-- Shares on rows that no longer exist (deleted while no trigger watched them) are dropped
DELETE FROM authz.shares g WHERE g.object_type = 'user' AND NOT EXISTS (SELECT 1 FROM "ms"."users" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'user' AND NOT EXISTS (SELECT 1 FROM "ms"."users" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'bot' AND NOT EXISTS (SELECT 1 FROM "ms"."bots" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'bot' AND NOT EXISTS (SELECT 1 FROM "ms"."bots" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'chat' AND NOT EXISTS (SELECT 1 FROM "ms"."chats" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'chat' AND NOT EXISTS (SELECT 1 FROM "ms"."chats" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'membership' AND NOT EXISTS (SELECT 1 FROM "ms"."members" x WHERE ROW(x."chat_id"::bigint, x."user_id"::uuid)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'membership' AND NOT EXISTS (SELECT 1 FROM "ms"."members" x WHERE ROW(x."chat_id"::bigint, x."user_id"::uuid)::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'message' AND NOT EXISTS (SELECT 1 FROM "ms"."messages" x WHERE ROW(x."chat_id"::bigint, x."seq"::bigint)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'message' AND NOT EXISTS (SELECT 1 FROM "ms"."messages" x WHERE ROW(x."chat_id"::bigint, x."seq"::bigint)::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'chat_bot' AND NOT EXISTS (SELECT 1 FROM "ms"."chat_bots" x WHERE ROW(x."chat_id"::bigint, x."bot_id"::bigint)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'chat_bot' AND NOT EXISTS (SELECT 1 FROM "ms"."chat_bots" x WHERE ROW(x."chat_id"::bigint, x."bot_id"::bigint)::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'block' AND NOT EXISTS (SELECT 1 FROM "ms"."blocks" x WHERE ROW(x."blocker_id"::uuid, x."blocked_id"::uuid)::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'block' AND NOT EXISTS (SELECT 1 FROM "ms"."blocks" x WHERE ROW(x."blocker_id"::uuid, x."blocked_id"::uuid)::text = g.subject_id);

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', '', true); END $r$;

-- Access for roles other than ms_app (e.g. from an earlier policy) is removed
DO $r$
DECLARE g record;
BEGIN
  FOR g IN SELECT DISTINCT a.grantee FROM pg_proc p, aclexplode(p.proacl) a
           WHERE p.pronamespace = 'authz'::regnamespace AND a.grantee NOT IN (p.proowner, 'ms_app'::regrole) LOOP
    EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM %s',
                   CASE WHEN g.grantee = 0 THEN 'PUBLIC' ELSE g.grantee::regrole::text END);
  END LOOP;
  FOR g IN SELECT DISTINCT a.grantee FROM pg_namespace n, aclexplode(n.nspacl) a
           WHERE n.nspname = 'authz' AND a.grantee NOT IN (n.nspowner, 'ms_app'::regrole) LOOP
    EXECUTE format('REVOKE ALL ON SCHEMA authz FROM %s',
                   CASE WHEN g.grantee = 0 THEN 'PUBLIC' ELSE g.grantee::regrole::text END);
  END LOOP;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO ms_app;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- policy.authz: every access rule of the messenger. Applied by db/migrate.py with authz.apply(); the
-- backend has no permission checks of its own. Read it top to bottom: people, bots, chats, then what
-- each table allows.

role ms_app

type user = ms.users (id uuid)
  has_blocked : user = ms.blocks(blocker_id -> blocked_id)  -- the people this person blocked
  can edit = {id = authz.uid()}                             -- your own profile

-- bots are services: they sign in with their own API keys (made by their owner) and post as themselves
type bot = ms.bots principal where {active}
  owner : user = owner_id
  can manage      = owner
  can manage_keys = owner

type chat = ms.chats
  member  : user = ms.members(chat_id -> user_id)
  admin   : user = ms.members(chat_id -> user_id) where {role in ('admin', 'owner')}
  owner   : user = ms.members(chat_id -> user_id) where {role = 'owner'}
  creator : user = created_by
  bot     : bot  = ms.chat_bots(chat_id -> bot_id)
  blocked : user = ms.direct_blocks(chat_id -> user_id)     -- a direct chat where one blocked the other
  invitee : link  shared by invite                          -- invite links: anyone holding one

  can read   = member or bot
  -- members post, unless blocked in a direct chat, or the group is for announcements and they aren't an admin
  can post   = (member and not blocked and ({not admins_only} or admin)) or bot
  can manage = admin and {kind = 'group'}                  -- the title, the members, bots, invite links
  can invite = manage
  can join   = (invitee and {kind = 'group'}) or manage     -- (admins may make links, so they hold what links give)
  -- a chat just created, before anyone is in it: its creator sees it and adds themselves
  can setup  = creator and {not exists (select 1 from ms.members m where m.chat_id = id)}
  -- adding people: admins of a group; the one who starts a direct chat adds the other person
  can add_members = manage or setup
                 or (creator and {kind = 'direct'} and {(select count(*) from ms.members m where m.chat_id = id) < 2})

-- a membership row: a person in a chat. Its key is (chat_id, user_id)
type membership = ms.members (chat_id, user_id uuid)
  chat   : chat = chat_id
  person : user = user_id

-- messages are numbered per chat; you read what was said since you joined
type message = ms.messages (chat_id, seq)
  chat     : chat = chat_id
  sender   : user = sender_id
  from_bot : bot  = bot_id

  can read   = chat.read and {created_at >= coalesce(ms.joined_at(chat_id), '-infinity')}
  can edit   = sender and {not deleted and created_at > now() - interval '15 minutes'}
  can remove = sender or chat.manage                       -- delete for everyone

type chat_bot = ms.chat_bots (chat_id, bot_id)
  chat : chat = chat_id
  bot  : bot  = bot_id

type block = ms.blocks (blocker_id uuid, blocked_id uuid)
  blocker : user = blocker_id

rules ms.users
  select                       : signed_in                  -- to find people by phone number
  update                       : edit
  update id, phone, created_at : {false}

rules ms.bots
  select            : signed_in
  insert            : {owner_id = authz.uid()}
  update            : manage
  update id, owner_id : {false}
  delete            : manage

rules ms.chats
  select                                 : read or join or setup
  insert                                 : signed_in and {created_by = authz.uid()}
  update                                 : manage
  update kind, created_by, created_at, last_seq : {false}
  delete                                 : owner and {kind = 'group'}

rules ms.members
  -- added by someone who may (not as an admin unless they are one), never someone who blocked you;
  -- or yourself, with an invite link
  insert                          : (chat.add_members and ({role = 'member'} or chat.manage or chat.setup)
                                     and not person.has_blocked)
                                    or (chat.join and person and {role = 'member'})
  select                          : chat.read
  update                          : chat.manage or person
  update role                     : chat.manage and {role <> 'owner'}       -- nobody demotes the owner
  update role after               : {role <> 'owner'}                        -- nor makes another
  update last_read_seq            : person
  update chat_id, user_id, joined_at : {false}
  delete                          : person or (chat.manage and {role <> 'owner'})   -- leave, or be removed

rules ms.messages
  select                          : read
  insert                          : chat.post and ((sender and {bot_id is null}) or (from_bot and {sender_id is null}))
  update                          : edit or remove
  update body after               : (edit and {not deleted}) or {deleted and body = ''}
  update deleted                  : remove
  update deleted after            : {deleted}                                -- no undelete
  update chat_id, seq, sender_id, bot_id, created_at : {false}
  delete                          : {false}                                  -- messages are deleted for everyone, not removed

rules ms.chat_bots
  select : chat.read
  insert : chat.manage and bot.manage and {added_by = authz.uid()}          -- your own bots, into chats you manage
  delete : chat.manage or bot.manage

rules ms.blocks
  select : blocker
  insert : blocker
  delete : blocker
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+ae5fccdf9a9b', '4d79f42bdcf10a9c');
